[6569]={["aftermath"]="Myranda accepted the reagents for a medallion whose illusion could deceive the Black Flight's gatekeeper.",["atomIDs"]={"6569:description:1-55","6569:description:60-189","6569:description:191-278","6569:description:283-415","6569:description:420-482","6569:objective:1-64","6569:objective:66-117"},["endingAtomIDs"]={"6569:completion:1-28","6569:completion:33-61","6569:completion:66-209"},["opening"]="Myranda could make the illusion required for the Warchief's mission, but its reagents lay in Blackrock's upper citadel. Eyes from the black dragonspawn would provide the needed material.",["pending"]="{actor} intended to gather twenty dragonspawn eyes for Myranda.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered twenty Black Dragonspawn Eyes to Myranda.",["sourceHash"]="7c86c4600e351dc7ec6e3b1d7dbb78436e47791c88f322cd45e76a4daa7e2bac",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
