[6583]={["atomIDs"]={"6583:description:1-122","6583:description:127-225","6583:description:230-318","6583:description:320-363","6583:description:365-394","6583:objective:1-55","6583:objective:57-100"},["opening"]="Emberstrife's next demand targeted the Green Flight. He sent the test toward the Swamp of Sorrows and its drake champion.",["pending"]="{actor} intended to recover the green champion's skull.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Somnus's skull to Emberstrife.",["sourceHash"]="b816633798bf4e098e1f253dbd8fe83a833596c510172e51f770ca6f1fb75d96",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
