[6601]={["atomIDs"]={"6601:description:1-53","6601:description:55-85","6601:description:87-132","6601:description:137-151","6601:description:153-209","6601:description:211-311","6601:description:316-463","6601:objective:1-42","6601:objective:44-169","6601:objective:171-230","6601:objective:232-266","6601:objective:268-306"},["opening"]="Emberstrife's medallion needed Drakkisath's final enchantment, but Myranda's disguise would fail inside the Spire. The predicament called for Rexxar rather than a blind continuation.",["pending"]="{actor} intended to show Rexxar the unfinished amulet.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the dull amulet to Rexxar.",["sourceHash"]="88788abf75f133e532294797502b0ba94631e8f97f2b55a40a95d884c8fe980b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
