[6847]={["atomIDs"]={"6847:description:1-68","6847:description:70-194","6847:description:199-240","6847:description:242-319","6847:description:324-413","6847:description:418-481","6847:description:486-506","6847:objective:1-92","6847:objective:97-186"},["opening"]="Master Ryson professed no loyalty to either army. The Syndicate would wait for a victor to weaken before striking, but his immediate concern was the All Seeing Eye taken by the Winterax. He offered temporary services in exchange for its recovery, despite warnings of a curse.",["pending"]="{actor} would seek Ryson's Eye in the Winterax caves.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the All Seeing Eye to Master Ryson.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="d3c646e50b665e32962f2214a4ab2a4157289aae006eae633eb3f62a1cb7cd81",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[6848]={["atomIDs"]={"6848:description:1-68","6848:description:70-194","6848:description:199-240","6848:description:242-319","6848:description:324-413","6848:description:418-481","6848:description:486-506","6848:objective:1-92","6848:objective:97-186"},["opening"]="The Winterax held an artifact that interested the Syndicate more than the war around it. Ryson wanted the All Seeing Eye returned from their caves, promising his services only for whatever time the recipient's side had left.",["pending"]="{actor} meant to recover the Eye for Ryson without assuming his allegiance.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Ryson's Eye from the Winterax caves.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="ee93f9721b65fd87009751d44774c2401830bcb86c1575ed60ad3181c4632514",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
