[6921]={["aftermath"]="Je'neu welcomed the information it could yield and expected it to help uncover the cult's intentions.",["atomIDs"]={"6921:description:1-79","6921:description:82-158","6921:description:161-215","6921:description:220-319","6921:description:322-430","6921:description:433-505","6921:objective:1-72"},["endingAtomIDs"]={"6921:completion:1-28","6921:completion:30-124","6921:completion:126-253","6921:completion:258-342","6921:completion:344-417"},["opening"]="Je'neu feared the cult's control of the elements within Blackfathom. A core from the submerged fathom stone could reveal the history of elemental activity to the Earthen Ring.",["pending"]="{actor} meant to recover the fathom core for Je'neu.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the Fathom Core to Zoram'gar.",["sourceHash"]="791ff4d1c46601a42ca1dfcb3f2e4d4c489412ee971fec8c55ef45e6cb2877d1",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
