[6985]={["atomIDs"]={"6985:description:1-69","6985:description:72-126","6985:description:129-231","6985:description:236-247","6985:description:250-361","6985:objective:1-72"},["opening"]="The Frostwolf quartermaster turned his attention to Irondeep, deep inside Stormpike territory. Raiding its stores would equip his own warriors while depriving the dwarves, though possession of the mine changed as readily as the valley's battle lines.",["pending"]="{actor} intended to recover ten Irondeep supply loads for Frostwolf Keep.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} handed the Irondeep supplies to the Frostwolf quartermaster.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="7d432415a91c61397734be1f382e1f697a85d79be591e9f6b55e0dce9eff3333",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7001]={["aftermath"]="The stable master hoped the wolf captures and the separate collection of harness hides would soon restore the riders.",["atomIDs"]={"7001:description:1-57","7001:description:59-88","7001:description:93-199","7001:description:204-282","7001:description:284-338","7001:description:340-409","7001:description:414-509","7001:objective:1-37","7001:objective:39-115","7001:objective:117-194","7001:objective:196-265"},["endingAtomIDs"]={"7001:completion:1-90","7001:completion:95-159"},["opening"]="Losses had emptied the Frostwolf stables. Wolves from the nearby forest could restore the riders' patrols, but each had to be caught with a muzzle and brought back; a filled stable was a collective aim rather than the work of one capture.",["pending"]="{actor} would muzzle a frostwolf and lead it to the stable master.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a captured frostwolf to the stable master.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="1ff3411d796f800a1fc1588bf69958c644853cc0dc57c593f533ac0355112aa0",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
