[7181]={["atomIDs"]={"7181:description:1-70","7181:description:72-116","7181:description:118-165","7181:description:170-236","7181:description:241-319","7181:description:321-351","7181:objective:1-127","7181:objective:132-210"},["opening"]="Laggrond's war had a second front in the Winterax. Their elusive leader, Korrak the Bloodrager, could appear on the field, and a strike against him might weaken the trolls' bid for the valley.",["pending"]="{actor} would seek Korrak if he appeared and report to Laggrond.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against Korrak for Laggrond.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="dbc3e4961c1daf15a782185e81d2fb7c0354c20a9ec28555e0d4f7463042e22b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7201]={["aftermath"]="Vivian arranged immediate shipment to the Undercity and honored the promised payment.",["atomIDs"]={"7201:description:1-64","7201:description:69-135","7201:description:140-273","7201:description:278-387","7201:description:389-479","7201:description:481-511","7201:objective:1-66","7201:objective:68-131","7201:objective:133-202"},["endingAtomIDs"]={"7201:completion:1-10","7201:completion:12-70","7201:completion:75-116","7201:completion:118-151"},["opening"]="Vivian's spies reported an unusual power source within the Dark Irons' golems. She wanted the elemental essence from Blackrock Depths for the possibilities it offered her own abominations.",["pending"]="{actor} intended to recover ten elemental essences for Vivian.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered ten Essence of the Elements.",["sourceHash"]="4aed0b933b907a479c2df2b57e693dc11d03063946d9747a592c4397da7f54ca",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7202]={["atomIDs"]={"7202:description:1-143","7202:description:148-175","7202:description:180-259","7202:description:261-396","7202:description:401-450","7202:description:452-471","7202:objective:1-127","7202:objective:132-237"},["opening"]="Recovered Winterax tomes described Korrak's place in the tribe's hierarchy. Haggerdin wanted the hidden leader defeated if he emerged, treating the trolls as a danger alongside the Frostwolves.",["pending"]="{actor} would watch for Korrak and carry the result to Haggerdin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Haggerdin's assignment against Korrak.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="55e1f2f04bb32928ee5303568c58c4fecb0417c053136c26dfe87a74a3153126",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7221]={["atomIDs"]={"7221:description:1-35","7221:description:38-90","7221:description:95-141","7221:description:144-201","7221:description:204-267","7221:description:272-320","7221:description:323-411","7221:objective:1-60"},["opening"]="The Stormpikes were gathering recruits for a mission into enemy territory. Stonehewer waited at the bottom of the Dun Baldar garrison with its purpose still to explain.",["pending"]="{actor} would speak with Prospector Stonehewer in the garrison.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported to Stonehewer at Dun Baldar.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="487769774f6e541f1d354b0ef6f6deac9de017b1d22ae4cbd04486f9fe6f6fbe",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7222]={["atomIDs"]={"7222:description:8-12","7222:description:15-52","7222:description:55-176","7222:description:181-208","7222:description:211-309","7222:description:314-352","7222:objective:1-36"},["opening"]="A further Horde mission led to Voggah Deathgrip in Frostwolf Keep. The task concerned the Alliance stronghold, but its details belonged to the briefing still ahead.",["pending"]="{actor} would find Voggah in Frostwolf Keep.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Voggah Deathgrip.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="32e9b18bd631e3c7f9e7cbe940636b24d02bbcc74a1b7a75efaa958d14b06a01",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7223]={["aftermath"]="Murgot intended to make equipment from the recovered pieces; the deployment of further units remained conditional on supply.",["atomIDs"]={"7223:description:1-130","7223:description:135-229","7223:objective:1-56"},["endingAtomIDs"]={"7223:completion:1-31","7223:completion:33-87","7223:completion:92-188"},["opening"]="Ironforge's regular shipments could not equip every experienced Stormpike soldier. Murgot Deepforge could turn armor scraps from the battlefield into gear for the troops, with a larger stockpile needed before further units could enter the field.",["pending"]="{actor} would bring twenty armor scraps to Murgot.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Murgot Deepforge with the armor scraps.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="e832d8077cbd3d5e6b3a32a7568d94d3e36b747de3eddc301c058ac0c8962f34",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7224]={["aftermath"]="Regzar accepted the pieces for reworking into equipment.",["atomIDs"]={"7224:description:1-80","7224:description:83-137","7224:objective:1-59"},["endingAtomIDs"]={"7224:completion:1-21","7224:completion:23-121","7224:completion:126-136","7224:completion:138-180"},["opening"]="Regzar saw material for Frostwolf armor in the wreckage of the enemy's. Collected scraps could be melted, patched and put back to use for his own troops.",["pending"]="{actor} would gather twenty armor scraps for Smith Regzar.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the scraps to Regzar in Frostwolf Village.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="bdd3bf8ecbecfbaa580904cd8844dd731e01f938a847f95fbf00ed2190b49d81",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7241]={["aftermath"]="Laggrond required a trial before accepting a soldier into the Frostwolf ranks.",["atomIDs"]={"7241:description:1-49","7241:description:51-148","7241:description:153-271","7241:description:276-335","7241:description:340-419","7241:description:421-470","7241:description:472-507","7241:objective:1-60","7241:objective:62-190","7241:objective:192-278"},["endingAtomIDs"]={"7241:completion:1-61"},["opening"]="Rokhstrom's summons led north of Tarren Mill to the valley's entrance. He called for defenders of Drek'Thar's clan and directed new soldiers to Laggrond before they entered the fighting.",["pending"]="{actor} would report to Warmaster Laggrond outside Alterac Valley.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} answered Rokhstrom's summons and met Laggrond.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="a825160cea5a875a259e57987e9d1dfa5dffec30aa1a155613c975a5fb705448",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7261]={["atomIDs"]={"7261:description:1-58","7261:description:60-162","7261:description:164-227","7261:description:229-344","7261:description:349-384","7261:description:386-498","7261:objective:1-52","7261:objective:54-126","7261:objective:131-159"},["opening"]="Rotimer presented the valley as an Ironforge territorial cause, threatened by Winterax trolls and Frostwolf forces alike. Haggerdin, outside the entrance tunnel, would begin the recruit's service with the Stormpikes.",["pending"]="{actor} planned to report to Haggerdin at Alterac Valley's entrance.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Lieutenant Haggerdin for the Stormpike tour of duty.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="883eba7d631a0f23ef2e794c1a617895265f2351acc1dcfde0f2b92a9112f59c",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7281]={["aftermath"]="Louis meant to contact Sylvanas without delay; his brother's fate after that appeal remained unresolved.",["atomIDs"]={"7281:description:1-9","7281:description:11-84","7281:description:89-159","7281:description:161-266","7281:description:271-323","7281:description:325-350","7281:description:352-416","7281:description:421-449","7281:objective:1-64","7281:objective:66-125"},["endingAtomIDs"]={"7281:completion:1-39","7281:completion:44-85","7281:completion:87-113"},["opening"]="Louis Philips faced his living brother across the battle lines. He hoped Sylvanas might turn Karl as she had turned him, but that hope first took the form of a mission against a dangerous Stormpike commander.",["pending"]="{actor} would confront Karl Philips and report to Louis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Louis Philips's assignment against his brother.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="9d8759dc0304db7b0173ef65e50a2f05c42ffc65c11ba1e95cc884b973c180ba",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7282]={["aftermath"]="Karl asked whether the corpse had been burned. The question did not establish that it had.",["atomIDs"]={"7282:description:1-42","7282:description:44-69","7282:description:71-132","7282:description:137-216","7282:description:218-249","7282:description:251-282","7282:objective:1-65","7282:objective:67-125"},["endingAtomIDs"]={"7282:completion:1-48"},["opening"]="Karl Philips regarded his brother's Forsaken service as torment. He wanted Louis destroyed beyond the Field of Strife, making the war between the armies a final conflict within their family.",["pending"]="{actor} would seek Louis Philips in Frostwolf territory.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Karl Philips's charge against Louis.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="207b980f39427d12073c37ba3686baff24a14c3be39eeb137c766a19eb067933",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7301]={["aftermath"]="Duffy welcomed their discovery but still asked whether they had actually been freed.",["atomIDs"]={"7301:description:1-30","7301:description:32-71","7301:description:73-131","7301:description:133-220","7301:description:222-262","7301:description:267-309","7301:description:311-348","7301:description:350-379","7301:objective:1-118","7301:objective:120-178"},["endingAtomIDs"]={"7301:completion:1-13","7301:completion:15-39","7301:completion:41-48","7301:completion:50-101"},["opening"]="Victory in the air had been followed by a costly Stormpike counterattack. Slidore, Vipore and Ichman were last known near Tower Point West and Frostwolf Keep; Duffy needed their whereabouts before more could be done.",["pending"]="{actor} would search Frostwolf territory for the missing wing commanders.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the search for the three wing commanders to Duffy.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="60c4a7a6a9bb2d67506d6e2b36e4da6cf466a500d636ce9b417e6e9c4e0800f1",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7302]={["aftermath"]="Mulfort considered the recovered information valuable to the cause.",["atomIDs"]={"7302:description:1-35","7302:description:37-92","7302:description:94-163","7302:description:168-217","7302:description:219-280","7302:description:282-293","7302:description:295-364","7302:description:369-402","7302:description:404-412","7302:description:414-449","7302:objective:1-97","7302:objective:99-159"},["endingAtomIDs"]={"7302:completion:1-10","7302:completion:12-73"},["opening"]="The Horde's air support had been shattered. Guse was last seen near Icewing, Jeztor near the Stormpike lumber mill and Mulverick near Dun Baldar's north bunker. Mulfort needed information that could make a rescue possible.",["pending"]="{actor} would search for Guse, Jeztor and Mulverick.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned to Mulfort with news of the missing commanders.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="0095ae534746f40721bdf3eb3fb1901f89c4789096fbbd6a619c3e3f3c6b0d61",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7321]={["aftermath"]="Christoph commended the warmth his bisque could offer on a cold night.",["atomIDs"]={"7321:description:1-59","7321:description:61-113","7321:description:115-187","7321:description:189-199","7321:description:204-261","7321:description:264-391","7321:description:396-495","7321:objective:1-93"},["endingAtomIDs"]={"7321:completion:1-63","7321:completion:65-101"},["opening"]="Christoph could no longer leave his work to hunt Lordamere's snapjaws. Turtle meat and soothing spices would allow a demonstration of his secret bisque recipe.",["pending"]="{actor} planned to bring ten portions of turtle meat and spices.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Christoph with the meat and soothing spices.",["sourceHash"]="401ea472b3f743b0cc5fd7b6e7e77292da9cdca970680924a0ff7e4da200eb3b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7361]={["atomIDs"]={"7361:description:1-15","7361:description:20-66","7361:description:68-111","7361:description:116-178","7361:description:180-264","7361:description:266-284","7361:description:289-387","7361:description:389-463","7361:description:465-495","7361:objective:1-79","7361:objective:84-175"},["opening"]="Najak Hexxen invoked an ancient quarrel with the night elves in support of the Darkspear. His offer of favor demanded a severed head from the opposing army, making the valley's war an instrument of that grievance.",["pending"]="{actor} would bring Najak proof from an opposing night elf.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a severed night elf head to Najak.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="a04ccc5881902ff4cd73e9f91f85a58c6959b233d00c0399fcdf316fbedd2b87",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7362]={["aftermath"]="Ravak recognized the sample and said the work was not yet finished.",["atomIDs"]={"7362:description:1-72","7362:description:74-122","7362:description:124-178","7362:description:180-283","7362:description:288-358","7362:description:360-445","7362:objective:1-75","7362:objective:80-166"},["endingAtomIDs"]={"7362:completion:1-30","7362:completion:32-80"},["opening"]="Ravak Grimtotem had come at Magatha's direction to study the resilience of gnomes. He sought hair from fallen opponents, with the offered tauren favor tied to that research rather than to the whole Horde's judgment.",["pending"]="{actor} would bring Ravak a tuft of gnome hair from the fighting.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Ravak with the requested gnome hair.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="965c8b28a46fb94f207bbcc499f91b956473069e264f85d0b7ead5c6500945d3",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7363]={["atomIDs"]={"7363:description:1-33","7363:description:38-66","7363:description:71-152","7363:description:157-251","7363:description:256-357","7363:description:362-417","7363:description:422-431","7363:description:433-442","7363:description:444-473","7363:objective:1-75","7363:objective:80-211","7363:objective:216-263"},["opening"]="Louis Philips served the Frostwolves while collecting material for the Undercity's apothecaries. His talk of curing the human condition gave a sinister purpose to the bone chips he demanded from fallen human opponents.",["pending"]="{actor} would deliver a human bone chip to Louis Philips.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Philips with the requested bone chip.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="6cb4e51ef63054908f5d3f2ca7b4f8304dfff0e473d7f4a7c7a806af55402462",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7364]={["atomIDs"]={"7364:description:1-104","7364:description:106-179","7364:description:181-272","7364:description:274-306","7364:description:308-327","7364:description:332-357","7364:description:359-380","7364:description:382-420","7364:objective:1-76","7364:objective:81-155"},["opening"]="Dirk Swindle described the collection of gnome hair as an atrocity against his people. Sent to defend them, he demanded tauren hooves in retaliation, answering one grim trophy trade with another.",["pending"]="{actor} would bring Dirk Swindle proof from a tauren opponent.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a tauren hoof to Dirk at Dun Baldar.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="2f62c68adab2eee6d77e76f0f87af2d35c2c8b6b9cb183132c281d77d3a0f0fe",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7365]={["atomIDs"]={"7365:description:1-29","7365:description:31-85","7365:description:87-177","7365:description:182-224","7365:description:226-270","7365:objective:1-75","7365:objective:80-157"},["opening"]="Athramanis relayed Staghelm's order against the trolls, rejecting their claims about night-elven origins. The demanded mojo turned that dispute into a bounty upon the opposing fighters.",["pending"]="{actor} would take Darkspear troll mojo to Athramanis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the requested mojo to Athramanis.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="3dfaca572fe52eb785a61a529879f3fc02ef860a8cfed2b32abf848a7f049c86",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7366]={["aftermath"]="Karl called for further such offerings in Benedictus's name; the later cathedral ceremony was not observed in this exchange.",["atomIDs"]={"7366:description:1-40","7366:description:42-95","7366:description:100-148","7366:description:153-163","7366:description:165-178","7366:description:183-276","7366:description:278-363","7366:description:368-475","7366:description:477-491","7366:objective:1-78","7366:objective:83-208"},["endingAtomIDs"]={"7366:completion:1-24","7366:completion:26-98","7366:completion:103-129","7366:completion:131-149"},["opening"]="Karl Philips spoke of permanent death for the Forsaken as mercy, invoking the Archbishop's authority. Hearts taken from fallen opponents were to be carried onward for burning at the Cathedral of Light.",["pending"]="{actor} would bring a Forsaken heart to Karl Philips.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the requested heart to Karl Philips.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="6801fc915ed250431a38b60436b55012c5e8c6df3412be81ab40f37f0d557ad9",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7367]={["atomIDs"]={"7367:description:1-65","7367:description:67-124","7367:description:129-279","7367:description:281-330","7367:description:332-389","7367:description:394-458","7367:description:460-469","7367:objective:1-50","7367:objective:52-119"},["opening"]="Frostwolf landmines threatened the Stormpike advance. Their explosives specialist argued that the enemy expert had to be eliminated first, preventing replacement of mines already disarmed.",["pending"]="{actor} would confront the Frostwolf explosives expert and report back.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against the Frostwolf explosives expert.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="b4bc2c16bb7580d49b63a1faeaa27df5a7be45b28a361520bbd3d0698d1af675",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7368]={["atomIDs"]={"7368:description:1-27","7368:description:29-99","7368:description:104-203","7368:description:205-285","7368:description:287-363","7368:description:368-428","7368:description:430-463","7368:objective:1-50","7368:objective:52-119"},["opening"]="The Frostwolf explosives expert knew what sustained the Stormpike minefields: their maker could keep replacing the traps. He placed that specialist in the first tower on the Field of Strife and wanted the source of the danger removed.",["pending"]="{actor} would seek the Stormpike explosives expert.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of the charge against the Stormpike expert.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="7981eea89eb2aa4a60bc42405625e238af75070aa0a05f07f5831ce531315cf8",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}
}
